#include <iostream>
#include <memory>
#include <string>
#define private public
#define protected public
#include "unicode/gregocal.h"
#include "unicode/simpletz.h"
#undef private
#undef protected
#include "unicode/locid.h"
#include "unicode/uloc.h"
#include "unicode/putil.h"
int main() {
  u_setDataDirectory("vendor/icu-reference/source/data/in");
  UErrorCode status=U_ZERO_ERROR;
  icu::Locale::setDefault(icu::Locale("en_US"),status);
  char buffer[12]; for(char &c:buffer)c=77;
  int length=uloc_getKeywordValue("en@a=   AbC   ;b=next","a",buffer,12,&status);
  std::cout<<"keyword "<<length<<' '<<int(status);
  for(int i=0;i<5;++i)std::cout<<' '<<int(static_cast<unsigned char>(buffer[i]));
  std::cout<<'\n';
  status=U_ZERO_ERROR;
  std::string locale="en_US@fw="+std::string(158,'x');
  icu::GregorianCalendar calendar(new icu::SimpleTimeZone(0,icu::UnicodeString(u"UTC")),icu::Locale("en_US"),status);
  auto cal=&calendar;
  status=U_ZERO_ERROR;
  cal->setWeekData(icu::Locale("en_US"),"gregorian",status);
  status=U_ZERO_ERROR;
  cal->setWeekData(icu::Locale(locale.c_str()),nullptr,status);
  std::cout<<"week "<<int(cal->getFirstDayOfWeek())<<' '<<int(cal->getMinimalDaysInFirstWeek())<<' '<<int(status)<<'\n';
}
